import { test, expect } from '@playwright/test';

test.describe('Save Search Query Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should save a search query successfully and display saved queries', async ({ page }) => {
    // Setup: Fill in search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('Playwright automation');

    // Setup: Click save button using getByRole
    const saveButton = page.getByRole('button', { name: /save search/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Search saved successfully');
    await expect(successMessage).toBeVisible();

    // Verify saved queries are displayed
    const savedQueriesList = page.getByRole('list', { name: /saved searches/i });
    await expect(savedQueriesList).toBeVisible();

    // Verify saved query is listed
    const savedQueryItem = page.getByText('Playwright automation');
    await expect(savedQueryItem).toBeVisible();

    // Verify search results are displayed
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Verify results contain expected content
    const resultItem = page.getByText('Playwright automation');
    await expect(resultItem).toBeVisible();

    // Verify search input is cleared
    await expect(searchInput).toHaveValue('');
  });

  test('should handle saving multiple queries and display all saved queries', async ({ page }) => {
    // Setup: Fill in first search input
    const searchInput1 = page.getByLabel('Search');
    await searchInput1.fill('Playwright automation');

    // Setup: Click save button for first query
    const saveButton1 = page.getByRole('button', { name: /save search/i });
    await saveButton1.click();

    // Verify success message for first query
    const successMessage1 = page.getByText('Search saved successfully');
    await expect(successMessage1).toBeVisible();

    // Setup: Fill in second search input
    const searchInput2 = page.getByLabel('Search');
    await searchInput2.fill('Playwright test scripts');

    // Setup: Click save button for second query
    const saveButton2 = page.getByRole('button', { name: /save search/i });
    await saveButton2.click();

    // Verify success message for second query
    const successMessage2 = page.getByText('Search saved successfully');
    await expect(successMessage2).toBeVisible();

    // Verify saved queries list contains both queries
    const savedQueriesList = page.getByRole('list', { name: /saved searches/i });
    await expect(savedQueriesList).toBeVisible();

    const savedQueryItem1 = page.getByText('Playwright automation');
    await expect(savedQueryItem1).toBeVisible();

    const savedQueryItem2 = page.getByText('Playwright test scripts');
    await expect(savedQueryItem2).toBeVisible();

    // Verify search results are displayed for both queries
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Verify results contain expected content for both queries
    const resultItem1 = page.getByText('Playwright automation');
    await expect(resultItem1).toBeVisible();

    const resultItem2 = page.getByText('Playwright test scripts');
    await expect(resultItem2).toBeVisible();

    // Verify search input is cleared after saving
    await expect(searchInput1).toHaveValue('');
    await expect(searchInput2).toHaveValue('');
  });
});
